"""The table models (common/tables.py, generated by common/tablegen.py) and Satellite's feed (common/satellite_feed.py):
the models say what the database is, and Satellite's export becomes rows the way the feed says."""
import json
import os

import pytest

from common import db, satellite_feed, tablegen, tables
from common.tables import Sor, SorItem

FAKE = ("SOR99990000003", "SOR99990000004")             # not real: no SO in Satellite has these


def test_the_models_are_what_the_database_is():
    """A migration changed the database but not the models? `python -m common.tablegen write`."""
    assert tablegen.check() == []


def test_every_table_has_its_key_among_its_columns():
    for name, table in tables.TABLES.items():
        assert tables.NAME[table] == name
        assert tables.KEYS[name] and set(tables.KEYS[name]) <= set(tables.columns(table)), name
    assert tables.select(Sor, without=("loaded_at",), prefix="s.").startswith("s.sor_no, s.customer_code")


def test_the_feed_says_where_every_satellite_column_comes_from():
    assert list(satellite_feed.SOR) == list(tables.columns(Sor))
    assert list(satellite_feed.SOR_ITEM) == list(tables.columns(SorItem))


def test_the_json_schemas_for_satellite_are_current():
    """docs/satellite-schema/*.schema.json: what a person writing Satellite's data for us works from. Not mounted in the API
    container (only services/ is): checked where the repo is whole."""
    if not os.path.isdir(tablegen.DOCS):
        pytest.skip("docs/ isn't here (the API container mounts services/ only)")
    with db.connect() as c:
        cat, enums = tablegen.catalog(c)
    for table, fields in (("satellite.sor", satellite_feed.SOR), ("satellite.sor_item", satellite_feed.SOR_ITEM)):
        described = {col: f"{m} (Satellite's export: {src})" if src else m for col, (src, m) in fields.items()}
        with open(os.path.join(tablegen.DOCS, table.split(".")[1] + ".schema.json")) as f:
            assert json.load(f) == tablegen.json_schema(cat, enums, table, described), table


def write_export(folder, lines_of):
    """The export's three files for the FAKE orders: {sor: [(line_no, item_code, qty)]}."""
    head = ["order_no", "order_id", "customer_id", "customer_name", "created_at", "inv_grand_total_amount",
            "inv_subtotal_after_discount_amount", "inv_vat_amount", "vat_percentage", "sap_bill_doc_no", "cgr_doc_no",
            "cgr_doc_date", "posting_date", "document_status", "subtotal_after_discount_amount", "vat_amount",
            "grand_total_amount", "ship_to_parent_customer_id"]
    item = ["order_id", "line_no", "item_code", "item_description", "ordered_uom_id", "conversion_factor", "ordered_qty",
            "ordered_base_qty", "price_list_amount", "base_price_list_amount", "total_discount_amount", "subtotal_amount",
            "total_amount", "vat_amount", "invoice_base_qty", "invoice_nett_amount", "cgr_base_qty",
            "cgr_rejected_base_qty", "cgr_reject_reason"] + [f"disc_{k}_{p}" for k in satellite_feed.DISCOUNTS
                                                             for p in ("type", "value", "amount")]
    csv = lambda cols, rows: "\n".join([",".join(cols)] + [",".join(str(r.get(c, "")) for c in cols) for r in rows]) + "\n"
    (folder / satellite_feed.HEADER_FILE).write_text(csv(head, [
        {"order_no": s, "order_id": f"id{i}", "customer_id": "TEST", "customer_name": "TEST STORE",
         "created_at": "2026-10-01 08:00:00", "inv_grand_total_amount": "111.00", "vat_percentage": "11.00",
         "grand_total_amount": "111.00", "subtotal_after_discount_amount": "100.00", "vat_amount": "11.00",
         "ship_to_parent_customer_id": "TESTCHAIN", "document_status": "CGR"} for i, s in enumerate(lines_of)]))
    (folder / satellite_feed.PO_FILE).write_text(csv(["order_no", "po_number", "sales_order_no"],
                                                     [{"order_no": s, "po_number": f"PO-{s[-1]}"} for s in lines_of]))
    (folder / satellite_feed.ITEM_FILE).write_text(csv(item, [
        {"order_id": f"id{i}", "line_no": n, "item_code": code, "item_description": "X", "ordered_uom_id": "CAR",
         "conversion_factor": "12", "ordered_qty": q, "ordered_base_qty": q * 12, "disc_reg_type": "percentage",
         "disc_reg_value": "10", "disc_reg_amount": "5"}
        for i, (s, ls) in enumerate(lines_of.items()) for n, code, q in ls]))


def test_an_export_becomes_rows_and_only_its_orders_lines_are_replaced(tmp_path):
    a, b = FAKE
    try:
        write_export(tmp_path, {a: [(10, "1000001", 2), (20, "1000002", 1)], b: [(10, "1000003", 5)]})
        orders, lines, counts = satellite_feed.read_export(tmp_path)
        assert counts == {"orders": 2, "with_po_number": 2, "lines": 3, "lines_without_order": 0, "only_in_po_file": 0}
        assert orders[0]["cpo_no"] == "PO-3" and orders[0]["order_total"] == 111.0 and orders[0]["tgl_so"] == "2026-10-01"
        assert lines[0]["discounts"] == {"reg": {"type": "percentage", "value": 10.0, "amount": 5.0}}
        with db.connect() as c:
            satellite_feed.upsert(c, orders, lines)
        # a newer export holds only order a, with one line left: a's lines are replaced, b keeps its own
        write_export(tmp_path, {a: [(10, "1000001", 3)]})
        orders, lines, _ = satellite_feed.read_export(tmp_path)
        with db.connect() as c:
            satellite_feed.upsert(c, orders, lines)
            got = {(r["sor_no"], r["line_no"]): r["qty_uom"] for r in c.execute(
                "SELECT sor_no, line_no, qty_uom FROM satellite.sor_item WHERE sor_no = ANY(%s)", (list(FAKE),))}
            so = c.execute("SELECT * FROM satellite.sor WHERE sor_no=%s", (a,)).fetchone()
        assert got == {(a, 10): 3, (b, 10): 5}
        assert set(so) == set(tables.columns(Sor)) and so["loaded_at"] is not None
    finally:
        with db.connect() as c:
            c.execute("DELETE FROM satellite.sor WHERE sor_no = ANY(%s)", (list(FAKE),))     # its lines go with it
